# Purpose: Houses helper functions for computing aerocapture quantities

import numpy as np
from .params_planet import gravParams, rotParams
import warnings

def pos_func(x, mu):
    r = x[0]
    return r

def apoRad_func(x, mu):
    r = x[0]
    V = x[3]
    gamma = x[4]
    a = mu / (2 * mu / r - V ** 2)
    ra = a * (1 + np.sqrt(1 - V ** 2 * r ** 2 * np.cos(gamma) ** 2 / (mu * a)))
    return ra

def finalPos_func(x, mu):
    r = x[0]
    return r

def energy_func(x, mu):
    r = x[0]
    V = x[3]
    energy = 0.5 * V ** 2 - mu / r
    return energy

def inertial2planetRel(planetName, v_I, gamma_I, h, psi, phi):
    r = h + gravParams[planetName].get('R_eq')
    omega = rotParams[planetName].get('Omega')
    v_planet_rel = np.sqrt(v_I * v_I - 2 * omega * r * v_I * np.cos(gamma_I) * np.cos(psi) * np.cos(phi) + (omega * r * np.cos(phi)) ** 2)
    gamma_planet_rel = np.arctan2(v_I * np.sin(gamma_I), np.sqrt((v_I * np.cos(gamma_I)) ** 2 - 2 * omega * r * v_I * np.cos(gamma_I) * np.cos( psi) * np.cos(phi) + (omega * r * np.cos(phi)) ** 2))

    return v_planet_rel, gamma_planet_rel


def getEnergyHistory(Xs, params):
    energies = []
    for x in Xs:
        energies.append(energy_func(x, gravParams[params['planetName']].get('mu')))
    return np.array(energies)

def energy_gradient(r, theta, phi, V, gamma, psi, rho, mu):
    grad = np.zeros(7)
    grad[0] = mu/r**2
    grad[1] = 0
    grad[2] = 0
    grad[3] = 1.0*V
    grad[4] = 0
    grad[5] = 0
    grad[6] = 0
    return grad

