def ra_gradient(r, theta, phi, V, gamma, psi, rho, mu):
    grad = np.zeros(7)
    grad[0] = 2*mu**2*(np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1) + 1)/(r**2*(-V**2 + 2*mu/r)**2) + mu*(V**2*np.cos(gamma)**2/mu - V**2*r*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/((-V**2 + 2*mu/r)*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1))
    grad[1] = 0
    grad[2] = 0
    grad[3] = 2*V*mu*(np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1) + 1)/(-V**2 + 2*mu/r)**2 + mu*(V**3*r**2*np.cos(gamma)**2/mu**2 - V*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/((-V**2 + 2*mu/r)*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1))
    grad[4] = V**2*r**2*np.sin(gamma)*np.cos(gamma)/(mu*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1))
    grad[5] = 0
    grad[6] = 0
    return grad

def ra_hessian(r, theta, phi, V, gamma, psi, rho, mu):
    H = np.zeros((7,7))
    H[0,0] = 8*mu**3*(np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1) + 1)/(r**4*(-V**2 + 2*mu/r)**3) + 4*mu**2*(V**2*np.cos(gamma)**2/mu - V**2*r*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/(r**2*(-V**2 + 2*mu/r)**2*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1)) - 4*mu**2*(np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1) + 1)/(r**3*(-V**2 + 2*mu/r)**2) + mu*(-V**2*np.cos(gamma)**2/mu + V**2*r*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)*(V**2*np.cos(gamma)**2/mu - V**2*r*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/((-V**2 + 2*mu/r)*(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1)**(3/2)) + mu*(2*V**2*np.cos(gamma)**2/(mu*r) - V**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/((-V**2 + 2*mu/r)*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1))
    H[0,1] = 0
    H[0,2] = 0
    H[0,3] = 8*V*mu**2*(np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1) + 1)/(r**2*(-V**2 + 2*mu/r)**3) + 2*V*mu*(V**2*np.cos(gamma)**2/mu - V**2*r*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/((-V**2 + 2*mu/r)**2*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1)) + 2*mu**2*(V**3*r**2*np.cos(gamma)**2/mu**2 - V*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/(r**2*(-V**2 + 2*mu/r)**2*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1)) + mu*(V**2*np.cos(gamma)**2/mu - V**2*r*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)*(-V**3*r**2*np.cos(gamma)**2/mu**2 + V*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/((-V**2 + 2*mu/r)*(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1)**(3/2)) + mu*(2*V**3*r*np.cos(gamma)**2/mu**2 + 2*V*np.cos(gamma)**2/mu - 2*V*r*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)/((-V**2 + 2*mu/r)*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1))
    H[0,4] = 2*V**2*np.sin(gamma)*np.cos(gamma)/((-V**2 + 2*mu/r)*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1)) - V**2*r**2*(V**2*np.cos(gamma)**2/mu - V**2*r*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2)*np.sin(gamma)*np.cos(gamma)/(mu*(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1)**(3/2)) + mu*(-2*V**2*np.sin(gamma)*np.cos(gamma)/mu + 2*V**2*r*(-V**2 + 2*mu/r)*np.sin(gamma)*np.cos(gamma)/mu**2)/((-V**2 + 2*mu/r)*np.sqrt(-V**2*r**2*(-V**2 + 2*mu/r)*np.cos(gamma)**2/mu**2 + 1))
    H[0,5] = 0
    H[0,6] = 0
    H[1,0] = 0
    H[1,1] = 0
    H[1,2] = 0
    H[1,3] = 0
    H[1,4] = 0
    H[1,5] = 0
    H[1,6] = 0
    H[2,0] = 0
